// string3 = "Loop finished\n"

main:
    // Program prologue
    ...
    // Printing the "Pre-test loop implementation" String
    ldr x0, =string1
    bl printf

    // Initialising the Loop variable (i)
    mov x20, 1
    b loopcond              // check the condition before the first pass

loopbody:
    ldr x0, =string2        // loading the format string
    mov x1, x20             // pass i to printf
    bl printf
    add x20, x20, 1

loopcond:
    cmp x20, 5
    b.le loopbody           // keep looping while i <= 5
    ldr x0, =string3
    bl printf

